-- EKB case-only learning for verified LF profile execution step 70/80.
-- Git-first; apply exclusively through existing governed Migration Merge Train.
-- Does not alter operational steps, judges, contracts, source RAW, permissions or status of existing EKB.
DO $ekb$
DECLARE v_inserted integer;
BEGIN
  IF (SELECT status FROM public.lf_operation_execution
      WHERE execution_id='EXEC-PROFILE-GATE2-458E10677E34F812D924F11F') IS DISTINCT FROM 'COMPLETED'
    OR (SELECT count(*) FROM public.lf_operation_execution_steps
        WHERE execution_id='EXEC-PROFILE-GATE2-458E10677E34F812D924F11F'
          AND status='STEP_PASS_WITH_EVIDENCE') <> 11
    OR (SELECT count(*) FROM public.lf_operation_execution_steps
        WHERE execution_id='EXEC-PROFILE-GATE2-458E10677E34F812D924F11F'
          AND step_id IN ('semantic_judge','report_output')) <> 2
    OR NOT EXISTS(SELECT 1 FROM transversal.error_knowledge
                  WHERE codigo='PROFILE-EXECUTION-SEMANTIC-JUDGE-NOT-ENFORCED-001'
                    AND estado='ACTIVE_REMEDIATION')
  THEN RAISE EXCEPTION 'LF_STEP70_EKB_PRESTATE_CHANGED'; END IF;

  INSERT INTO transversal.error_knowledge
    (codigo,categoria,titulo,descripcion,causa_raiz,prevencion,validacion,
     severidad,lote_origen,estado,evidencia,lifecycle_phase,
     root_cause_family,detectability,source_context,source_ref,consumer_role)
  VALUES
  ('LF-PE-STEP70-CHAT-VERDICT-NOT-PERSISTED-20261031-001', 'PROFILE_RUNTIME_GOVERNANCE', 'Dictamen semantico favorable fuera de pase gobernado dejo run 9/11', 'Issue #3432 tenia revision semantica favorable 11/11 aplicables + check 11 NOT_TESTED/ROUTER_ONLY, pero el run 458E1067 seguia IN_PROGRESS con 9/11 al no existir fila semantic_judge ni report_output. El dictamen en chat por si solo no acciona el registrador.', 'Se confundio elaborar el dictamen con ejecutar la continuacion gobernada del run.', 'Al producir un dictamen del juez asociar el execution_id exacto, entregar el V3 al canal de continuacion gobernado existente (solicitud GitHub + etiqueta lf-profile-resume-governed) y exigir readback de semantic_judge antes de declarar completado. No rehacer juicio semantico ni crear ruta paralela.', 'Issue #3436 activo workflow GitHub run 41258310552 SUCCESS; Supabase readback mismo execution_id: semantic_judge PASS, report_output PASS, run COMPLETED 11/11; recanonicalization not required.', 'HIGH', 'LF_PROFILE_458E1067_20261031', 'VERIFICADO', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432#issuecomment-6551372977; github://cristhianlujan/claude-persona-lf-patch/issues/3436; github-actions://cristhianlujan/claude-persona-lf-patch/actions/runs/41258310552', 'RUNTIME_LIVE_REVERIFY', 'R5_EROSION_PROCESO', 'LOUD_LATE', 'EXEC-PROFILE-GATE2-458E10677E34F812D924F11F', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432',ARRAY['Architect','Builder','Judge','Auditor']::text[]),
('LF-PE-STEP70-MODEL-RECEIPT-NOT-ATTESTED-20261031-002', 'PROFILE_RUNTIME_GOVERNANCE', 'Resumen V3 sin prueba de llamada e independencia no es recibo registrable', 'El JSON preparado de Issue #3432 tenia producer_independence_proven, model_call_count e independent_semantic_receipt_ref no acreditados. Un resultado humano favorable no constituye automaticamente un recibo de invocacion independiente y no autoriza inventar esos tres valores.', 'La preparacion documental del dictamen y su recibo de ejecucion no estaban unidos al mismo pase gobernado.', 'El revisor debe entregar un V3 fuente-a-fuente con 12 checks, independencia real, llamada verificable, 2 digests originales, y referencia del artefacto persistido; el transporte genera el actions:// receipt correspondiente al run real. No colocar true, 1 ni ruta ficticia para evitar validacion.', 'GitHub run 41258310552 artifact profile-native-output-41258310552 contiene profile-semantic-judge.json. Supabase semantic_judge incluye candidate=815f6401..., scope=31d65a5e..., model_call_count=1, producer_independence_proven=true, check11 not_applicable ROUTER_ONLY; trust V2 valid=true. La prueba de independencia de proveedor fuera del recibo no se infiere.', 'HIGH', 'LF_PROFILE_458E1067_20261031', 'VERIFICADO', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432#issuecomment-6551372977; github://cristhianlujan/claude-persona-lf-patch/issues/3436; github-actions://cristhianlujan/claude-persona-lf-patch/actions/runs/41258310552', 'RUNTIME_LIVE_REVERIFY', 'R4_NO_CUESTIONA', 'PROCESS_DEPENDENT', 'EXEC-PROFILE-GATE2-458E10677E34F812D924F11F', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432',ARRAY['Architect','Builder','Judge','Auditor']::text[]),
('LF-PE-STEP70-WRITER-DIAGNOSIS-BEFORE-INSERT-20261031-003', 'PROFILE_RUNTIME_GOVERNANCE', 'Se atribuyo a tabla/ACL una falla que estaba antes de invocar el RPC', 'Mientras 9 pasos estaban guardados, se buscaron alteraciones de codigo y se atribuyo bloqueo al conector Supabase read-only. Comparacion en vivo demostro que un run exitoso 103C8E0 y el run 458E1067 usaban identico lf_record_profile_execution_step_v1 -> lf_record_operation_step_core_v1 -> INSERT. Para 458E1067 no se habia invocado el pase semantico en esa etapa.', 'Se omitio contrastar parametro por parametro y ruta por ruta un step exitoso antes de diagnosticar la falla; se mezclo permiso del conector read-only con la capacidad service_role del workflow.', 'Ante step ausente: leer EKB, contratos, ACL por rol, core_recorder y evidence_payload del ultimo paso limpio; comparar contra run terminado y migracion gobernada real; separar PRE_INSERT, RPC_REJECTED, INSERT_ERROR y READBACK_FAILED; no modificar escritor sin reproducir error SQL literal.', 'Run 103C8E0 tenia 70/80 PASS via migration 20261031035000/35001. Run 458E1067 se cerro 11/11 mediante GitHub issue #3436 y Actions 41258310552 SIN cambiar RPC, columnas o Core; terminal_authority_receipt READY.', 'HIGH', 'LF_PROFILE_458E1067_20261031', 'VERIFICADO', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432#issuecomment-6551372977; github://cristhianlujan/claude-persona-lf-patch/issues/3436; github-actions://cristhianlujan/claude-persona-lf-patch/actions/runs/41258310552', 'RUNTIME_LIVE_REVERIFY', 'R2_NO_VE', 'PROCESS_DEPENDENT', 'EXEC-PROFILE-GATE2-458E10677E34F812D924F11F', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432',ARRAY['Architect','Builder','Judge','Auditor']::text[]),
('LF-PE-STEP70-GITHUB-TOOL-DENIAL-PARTIAL-BRANCH-20261031-004', 'PROFILE_RUNTIME_GOVERNANCE', 'Bloqueo de herramienta Git no equivale a error de parametros SQL', 'Al intentar arreglar el writer se obtuvo literalmente ''Los controles de seguridad de OpenAI bloquearon esta llamada a la herramienta''. Un primer cambio Python alcanzo la rama fix/lf-step70-judge-outcome-persist-20261031; posterior cambio Edge/SQL y el intento de revertir fueron rechazados por la herramienta. No fue retorno PostgreSQL ni SQLSTATE.', 'Se salto la ruta oficial de registro y se intento parchear codigo sin haber localizado el INSERT existente; luego se mezclo rechazo del host Git con falla SQL.', 'Capturar punto exacto de rechazo y resultado del API: TOOL_DENIAL_PRE_GITHUB vs GH_HTTP vs RPC_SQLSTATE; no especular parametros. Si una secuencia de cambios queda parcial, prohibir merge y hacer readback de main/rama para limpieza autorizada en lote independiente.', 'Main no incluyo el parche fallido y cerró el run via pase oficial. Pendiente readback/limpieza de rama fix/lf-step70-judge-outcome-persist-20261031; no declarar reparacion de codigo por este intento.', 'MEDIUM', 'LF_PROFILE_458E1067_20261031', 'ACTIVO', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432#issuecomment-6551372977; github://cristhianlujan/claude-persona-lf-patch/issues/3436; github-actions://cristhianlujan/claude-persona-lf-patch/actions/runs/41258310552', 'RUNTIME_LIVE_REVERIFY', 'R5_EROSION_PROCESO', 'LOUD_EARLY', 'EXEC-PROFILE-GATE2-458E10677E34F812D924F11F', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432',ARRAY['Architect','Builder','Judge','Auditor']::text[]),
('LF-PE-STEP70-RUN-CLOSED-EKB-ENFORCEMENT-OPEN-20261031-005', 'PROFILE_RUNTIME_GOVERNANCE', 'Cierre 11/11 de un run no acredita enforcement negativo del juez', 'Run 458E1067 logro COMPLETED 11/11 con step70/80 PASS; sin embargo EKB PROFILE-EXECUTION-SEMANTIC-JUDGE-NOT-ENFORCED-001 permanece ACTIVE_REMEDIATION. Un PASS positivo no demuestra que el trust validator rechace FAIL o unsupported_claims en todos los caminos.', 'Riesgo de confundir cierre de un caso positivo con reparacion global y verificacion negativa del enforcement server-side.', 'Mantener estados separados: execution terminal READY vs EKB de enforcement. Antes de cerrar el EKB critico ejecutar canaries positivos y negativos reales con FAIL, unsupported_claims y PASS limpio; leer status BLOCKED/PASS en Supabase y comprobar no contaminacion del terminal.', 'Run 41258310552 y Supabase confirman step70/80 PASS y terminal READY sha256:9be85a2de8730882e274d81f0ee104327e744832f1f48884254bff40f866fa7a. EKB principal ACTIVE_REMEDIATION; canary negativo actualizado aun pendiente de prueba en este lote.', 'CRITICAL', 'LF_PROFILE_458E1067_20261031', 'ACTIVO', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432#issuecomment-6551372977; github://cristhianlujan/claude-persona-lf-patch/issues/3436; github-actions://cristhianlujan/claude-persona-lf-patch/actions/runs/41258310552', 'RUNTIME_LIVE_REVERIFY', 'R4_NO_CUESTIONA', 'PROCESS_DEPENDENT', 'EXEC-PROFILE-GATE2-458E10677E34F812D924F11F', 'github://cristhianlujan/claude-persona-lf-patch/issues/3432',ARRAY['Architect','Builder','Judge','Auditor']::text[])
  ON CONFLICT(codigo) DO NOTHING;

  IF (SELECT count(*) FROM transversal.error_knowledge
      WHERE codigo IN ('LF-PE-STEP70-CHAT-VERDICT-NOT-PERSISTED-20261031-001', 'LF-PE-STEP70-MODEL-RECEIPT-NOT-ATTESTED-20261031-002', 'LF-PE-STEP70-WRITER-DIAGNOSIS-BEFORE-INSERT-20261031-003', 'LF-PE-STEP70-GITHUB-TOOL-DENIAL-PARTIAL-BRANCH-20261031-004', 'LF-PE-STEP70-RUN-CLOSED-EKB-ENFORCEMENT-OPEN-20261031-005')) <> 5
  THEN RAISE EXCEPTION 'LF_STEP70_EKB_READBACK_MISSING_OR_DUPLICATE'; END IF;

  IF (SELECT count(*) FROM transversal.error_knowledge
      WHERE codigo='PROFILE-EXECUTION-SEMANTIC-JUDGE-NOT-ENFORCED-001'
        AND estado='ACTIVE_REMEDIATION') <> 1
  THEN RAISE EXCEPTION 'LF_STEP70_EKB_EXISTING_CRITICAL_STATUS_CHANGED'; END IF;
END $ekb$;
